138	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
139	     *  separated by '@', none of which contain whitespace or a second '@'. */
140	    private static final java.util.regex.Pattern EMAIL_PATTERN =
141	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
142	
143	    /** Disposable email domains that are not accepted as an owner's email. */
144	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
145	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
146	
147	    /**
148	     * Normalize the optional email: absent stays absent; when present it must be syntactically
149	     * valid and is lower-cased. Returns {@code false} if present but invalid, including when its
150	     * domain is on the disposable-domain blocklist.
151	     */
152	    private boolean normalizeEmail(Owner owner) {
153	        String email = owner.getEmail();
154	        if (email == null || email.isEmpty()) {
155	            owner.setEmail(null);
156	            return true;
157	        }
158	        if (!EMAIL_PATTERN.matcher(email).matches()) {
159	            return false;
160	        }
161	        email = email.toLowerCase(java.util.Locale.ROOT);
162	        String domain = email.substring(email.indexOf('@') + 1);
163	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
164	            return false;
165	        }
166	        owner.setEmail(email);
167	        return true;
168	    }
169	
170	    /**
171	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
172	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
173	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
174	     *
175	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
176	     *         a valid E.164 number.
177	     */
178	    private static String toE164(String raw) {
179	        if (raw == null) {
180	            return null;
181	        }
182	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
183	        String digits;
184	        if (cleaned.startsWith("+")) {
185	            digits = cleaned.substring(1);
186	        } else {
187	            if (cleaned.startsWith("0")) {
188	                cleaned = cleaned.substring(1);
189	            }
190	            digits = "61" + cleaned;
191	        }
192	        if (!digits.matches("\\d{8,15}")) {
193	            return null;
194	        }
195	        return "+" + digits;
196	    }
197	
198	    /**
199	     * Validate the national-number length of a canonical E.164 string against its country code:
200	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
201	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
202	     * string produced by {@link #toE164}.
203	     *
204	     * @return {@code true} when the national-number length is correct for the country code.
205	     */
206	    private static boolean hasValidNationalLength(String e164) {
207	        String digits = e164.substring(1);
208	        if (digits.startsWith("61")) {
209	            return digits.length() - 2 == 9;
210	        }
211	        if (digits.startsWith("1")) {
212	            return digits.length() - 1 == 10;
213	        }
214	        return true;
215	    }
216	
217	    /**
218	     * Build the unified member id {@code <REGION><FY><HASH8><CHK>}: REGION is the region code derived
219	     * from the owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN} when the postcode is absent or in no
220	     * known range); FY is the two-digit fiscal year of the owner's (business-day-adjusted)
221	     * registrationDate; HASH8 is the first 8 upper-case hex characters of SHA-256 over the
222	     * concatenation of the owner's normalized (E.164) telephone and last name; and CHK is a single
223	     * Luhn check digit over the digits of {@code <REGION><FY><HASH8>} (e.g. {@code NSW273F9A0C177}).
224	     * No sequence numbers are used, so the base id is a pure function of the owner's region, fiscal
225	     * year and region-and-hash identity. When that base id collides with an existing owner's memberId,
226	     * {@code -<n>} is appended with the smallest {@code n} of 2 or more that makes it unique, returning
227	     * the de-duplicated id.
228	     */
229	    private String memberIdFor(Owner owner) {
230	        String region = ownerMapper.regionFromPostcode(owner);
231	        if (region == null) {
232	            region = "UNKNOWN";
233	        }
234	        String fy = String.format("%02d", ownerMapper.fiscalYearOf(owner.getRegistrationDate()) % 100);
235	        String core = region + fy + hash8(owner.getTelephone(), owner.getLastName());
236	        String base = core + luhn(core);
237	
238	        java.util.Set<String> existingIds = new java.util.HashSet<>();
239	        for (Owner existing : this.clinicService.findAllOwners()) {
240	            String id = existing.getMemberId();
241	            if (id != null) {
242	                existingIds.add(id);
243	            }
244	        }
245	        if (!existingIds.contains(base)) {
246	            return base;
247	        }
248	        for (int n = 2; ; n++) {
249	            String candidate = base + "-" + n;
250	            if (!existingIds.contains(candidate)) {
251	                return candidate;
252	            }
253	        }
254	    }
255	
256	    /**
257	     * A single Luhn check digit (0-9) over the digits contained in {@code value}; non-digit characters
258	     * are ignored.
259	     */
260	    private static int luhn(String value) {
261	        int sum = 0;
262	        boolean dbl = true;
263	        for (int i = value.length() - 1; i >= 0; i--) {
264	            char c = value.charAt(i);
265	            if (c < '0' || c > '9') {
266	                continue;
267	            }
268	            int d = c - '0';
269	            if (dbl) {
270	                d *= 2;
271	                if (d > 9) {
272	                    d -= 9;
273	                }
274	            }
275	            sum += d;
276	            dbl = !dbl;
277	        }
278	        return (10 - (sum % 10)) % 10;
279	    }
280	
281	    /**
282	     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
283	     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
284	     */
285	    private static String hash8(String normalizedTelephone, String lastName) {
286	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
287	            + (lastName == null ? "" : lastName);
288	        try {
289	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
290	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
291	            StringBuilder sb = new StringBuilder(8);
292	            for (int i = 0; i < 4; i++) {
293	                sb.append(String.format("%02X", digest[i]));
294	            }
295	            return sb.toString();
296	        }
297	        catch (java.security.NoSuchAlgorithmException e) {
298	            throw new IllegalStateException(e);
299	        }
300	    }
301	
302	    /** Common street-type abbreviations expanded during address normalization. */
303	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
304	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
305	
306	    /**
307	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
308	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
309	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
310	     */
311	    private static String normalizeAddress(String value) {
312	        if (value == null) {
313	            return "";
314	        }
315	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
316	        if (collapsed.isEmpty()) {
317	            return "";
318	        }
319	        String[] tokens = collapsed.split(" ");
320	        StringBuilder sb = new StringBuilder(collapsed.length());
321	        for (int i = 0; i < tokens.length; i++) {
322	            if (i > 0) {
323	                sb.append(' ');
324	            }
325	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
326	        }
327	        return sb.toString();
328	    }
329	
330	    /**
331	     * Resolve and normalize the owner's postal address, preferring the structured form.
332	     *
333	     * <p>When a non-blank {@code addressLine1} is supplied the structured form is used: it, and the
334	     * optional {@code addressLine2}, are normalized in place and the composed address is the
335	     * normalized addressLine1 with a single space and the normalized addressLine2 appended when
336	     * addressLine2 is present. Otherwise the flat {@code address} input is normalized. Returns
337	     * {@code null} when neither form yields a non-empty address, so the caller can reject the
338	     * request.
339	     */
340	    private String composeAddress(Owner owner) {
341	        String line1 = owner.getAddressLine1();
342	        if (line1 != null && !line1.isBlank()) {
343	            String normalizedLine1 = normalizeAddress(line1);
344	            owner.setAddressLine1(normalizedLine1);
345	            String line2 = owner.getAddressLine2();
346	            if (line2 != null && !line2.isBlank()) {
347	                String normalizedLine2 = normalizeAddress(line2);
348	                owner.setAddressLine2(normalizedLine2);
349	                return normalizedLine1 + " " + normalizedLine2;
350	            }
351	            owner.setAddressLine2(null);
352	            return normalizedLine1.isEmpty() ? null : normalizedLine1;
353	        }
354	        String normalized = normalizeAddress(owner.getAddress());
355	        return normalized.isEmpty() ? null : normalized;
356	    }
357	
358	    /**
359	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
360	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
361	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
362	     */
363	    private static String normalizeForHousehold(String value) {
364	        if (value == null) {
365	            return "";
366	        }
367	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
368	    }
369	
370	    /**
371	     * Return the owners that already share this owner's household, i.e. resolve to the same
372	     * deterministic {@link #householdIdFor(Owner) householdId} (same normalized last name and
373	     * postcode).
374	     */
375	    private List<Owner> householdMembers(Owner owner) {
376	        String householdId = householdIdFor(owner);
377	        List<Owner> members = new java.util.ArrayList<>();
378	        for (Owner existing : this.clinicService.findAllOwners()) {
379	            if (existing.isDeleted()) {
380	                continue;
381	            }
382	            if (householdId.equals(householdIdFor(existing))) {
383	                members.add(existing);
384	            }
385	        }
386	        return members;
387	    }
388	
389	    /**
390	     * Return {@code true} when another owner already shares this owner's household, i.e. resolves to
391	     * the same deterministic {@link #householdIdFor(Owner) householdId}.
392	     */
393	    private boolean sharesHouseholdWithExisting(Owner owner) {
394	        return !householdMembers(owner).isEmpty();
395	    }
396	
397	    /**
398	     * Count the existing owners that share this owner's first name and last name, compared
399	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
400	     */
401	    private int namesakeCount(Owner owner) {
402	        String firstName = owner.getFirstName();
403	        String lastName = owner.getLastName();
404	        int count = 0;
405	        for (Owner existing : this.clinicService.findAllOwners()) {
406	            if (firstName != null && lastName != null
407	                && firstName.equalsIgnoreCase(existing.getFirstName())
408	                && lastName.equalsIgnoreCase(existing.getLastName())) {
409	                count++;
410	            }
411	        }
412	        return count;
413	    }
414	
415	    /**
416	     * A stable, shared household identifier: the first 12 hex characters of SHA-256 over
417	     * {@code normalizedLastName + '|' + postcode} (an absent postcode contributes an empty string).
418	     * Because it is a pure function of the last name and postcode, every owner in the same household
419	     * deterministically resolves to the same value.
420	     */
421	    private static String householdIdFor(Owner owner) {
422	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
423	        String key = normalizeForHousehold(owner.getLastName()) + "|" + postcode;
424	        try {
425	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
426	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
427	            StringBuilder sb = new StringBuilder(12);
428	            for (int i = 0; i < 6; i++) {
429	                sb.append(String.format("%02X", digest[i]));
430	            }
431	            return sb.toString();
432	        }
433	        catch (java.security.NoSuchAlgorithmException e) {
434	            throw new IllegalStateException(e);
435	        }
436	    }
437	
438	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
439	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
440	        "NSW", new int[] {2000, 2099},
441	        "VIC", new int[] {3000, 3099},
442	        "QLD", new int[] {4000, 4099});
443	
444	    /**
445	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
446	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
447	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
448	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
449	     * postcode.
450	     */
451	    private boolean isPostcodeValid(Owner owner) {
452	        String postcode = owner.getPostcode();
453	        if (postcode == null || postcode.isEmpty()) {
454	            return true;
455	        }
456	        if (!postcode.matches("\\d{4}")) {
457	            return false;
458	        }
459	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
460	        if (range == null) {
461	            return true;
462	        }
463	        int value = Integer.parseInt(postcode);
464	        return value >= range[0] && value <= range[1];
465	    }
466	
467	    /**
468	     * Find an existing owner that makes this (already known to be non-hard-duplicate) owner a
469	     * "possible duplicate": one whose last name shares this owner's {@link Owner#soundex(String)
470	     * soundex} and whose postcode matches, yet whose whole {@link Owner#getIdentityKey() identityKey}
471	     * differs (so it is not a hard duplicate). When several match, the one with the smallest id is
472	     * chosen so the result is deterministic. Returns {@code null} when the owner has no postcode or no
473	     * such existing owner exists.
474	     */
475	    private Owner possibleDuplicateOf(Owner owner) {
476	        String lastName = owner.getLastName();
477	        String postcode = owner.getPostcode();
478	        if (lastName == null || postcode == null || postcode.isEmpty()) {
479	            return null;
480	        }
481	        String soundex = Owner.soundex(lastName);
482	        String identityKey = owner.getIdentityKey();
483	        Owner match = null;
484	        for (Owner existing : this.clinicService.findAllOwners()) {
485	            if (soundex.equals(Owner.soundex(existing.getLastName()))
486	                && postcode.equals(existing.getPostcode())
487	                && !identityKey.equals(existing.getIdentityKey())) {
488	                if (match == null || (existing.getId() != null && match.getId() != null
489	                    && existing.getId() < match.getId())) {
490	                    match = existing;
491	                }
492	            }
493	        }
494	        return match;
495	    }
