497	    /** Maximum number of owners permitted in a single city. */
498	    private static final int CITY_CAPACITY = 50;
499	
500	    /**
501	     * Number of owners already in a city at or beyond which a capacity warning is flagged (the city
502	     * is approaching the {@link #CITY_CAPACITY} hard limit). A city holding 40-49 owners warns.
503	     */
504	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
505	
506	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
507	    private static final int DAILY_CREATE_LIMIT = 100;
508	
509	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
510	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
511	
512	    /**
513	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
514	     * Used to enforce the per-city capacity on create (before this owner is saved).
515	     */
516	    private int cityOwnerCount(Owner owner) {
517	        String city = owner.getCity();
518	        int count = 0;
519	        for (Owner existing : this.clinicService.findAllOwners()) {
520	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
521	                count++;
522	            }
523	        }
524	        return count;
525	    }
526	
527	    /** Fixed public holidays the business-day roll skips. */
528	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
529	        java.time.LocalDate.parse("2026-01-01"),
530	        java.time.LocalDate.parse("2026-01-26"),
531	        java.time.LocalDate.parse("2026-04-25"),
532	        java.time.LocalDate.parse("2026-12-25"),
533	        java.time.LocalDate.parse("2026-12-28"));
534	
535	    /**
536	     * Roll a registration date forward onto a business day: any Saturday, Sunday or listed public
537	     * holiday is advanced one day at a time until a non-holiday weekday is reached; a date that is
538	     * already a non-holiday weekday is returned unchanged. Applied to the effective registration date
539	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
540	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
541	     */
542	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
543	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
544	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
545	            || PUBLIC_HOLIDAYS.contains(date)) {
546	            date = date.plusDays(1);
547	        }
548	        return date;
549	    }
550	
551	    /**
552	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
553	     * per-day create limit on create (before this owner is saved).
554	     */
555	    private int ownersRegisteredOn(java.time.LocalDate day) {
556	        int count = 0;
557	        for (Owner existing : this.clinicService.findAllOwners()) {
558	            if (day.equals(existing.getRegistrationDate())) {
559	                count++;
560	            }
561	        }
562	        return count;
563	    }
564	
565	    /**
566	     * The {@code Idempotency-Key} header of the request currently being handled, or {@code null} when
567	     * the header is absent, blank or no servlet request is bound to the calling thread. The generated
568	     * {@link OwnersApi#addOwner} signature carries no header parameter, so it is read from the bound
569	     * request context.
570	     */
571	    private static String currentIdempotencyKey() {
572	        org.springframework.web.context.request.RequestAttributes attrs =
573	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
574	        if (attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs) {
575	            String key = servletAttrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
576	            if (key != null && !key.isBlank()) {
577	                return key;
578	            }
579	        }
580	        return null;
581	    }
582	
583	    /**
584	     * The owner's primary identifier, carried by the structured owner-created audit event: the
585	     * unified {@code memberId}.
586	     */
587	    private String primaryIdentifier(Owner owner) {
588	        return owner.getMemberId();
589	    }
590	
591	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
592	    @Override
593	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
594	        HttpHeaders headers = new HttpHeaders();
595	        // Idempotent create: when this request carries an Idempotency-Key we have already seen, return
596	        // the owner originally created for that key (200) instead of creating a duplicate.
597	        String idempotencyKey = currentIdempotencyKey();
598	        if (idempotencyKey != null) {
599	            Integer existingId = idempotentCreates.get(idempotencyKey);
600	            if (existingId != null) {
601	                Owner existing = this.clinicService.findOwnerById(existingId);
602	                if (existing != null) {
603	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
604	                }
605	            }
606	        }
607	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
608	        if (!isPostcodeValid(owner)) {
609	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
610	                "The postcode is invalid for the owner's city");
611	        }
612	        String telephone = toE164(owner.getTelephone());
613	        if (telephone == null || !hasValidNationalLength(telephone)) {
614	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
615	                "The telephone number is missing or not a valid number");
616	        }
617	        if (!normalizeEmail(owner)) {
618	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
619	                "The email address is not valid");
620	        }
621	        String address = composeAddress(owner);
622	        if (address == null) {
623	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
624	                "The address is missing or incomplete");
625	        }
626	        owner.setAddress(address);
627	        owner.setTelephone(telephone);
628	        if (owner.getRegistrationDate() != null
629	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
630	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
631	                "The registration date cannot be in the future");
632	        }
633	        java.time.LocalDate registrationDate = toBusinessDay(
634	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
635	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
636	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
637	            throw new RestApiRejectionException(HttpStatus.TOO_MANY_REQUESTS,
638	                "The daily owner creation limit has been reached");
639	        }
640	        int cityOwnerCount = cityOwnerCount(owner);
641	        if (cityOwnerCount >= CITY_CAPACITY) {
642	            throw new RestApiRejectionException(HttpStatus.CONFLICT,
643	                "The owner's city has reached its capacity");
644	        }
645	        // The householdId is deterministic (SHA-256 over normalized lastName + '|' + postcode), so
646	        // owners with the same last name and postcode automatically share it. The link is no longer
647	        // created by copying an existing owner's id around.
648	        owner.setHouseholdId(householdIdFor(owner));
649	        List<Owner> householdMembers = householdMembers(owner);
650	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
651	        boolean declaredHouseholdMember = sharesHousehold && !householdMembers.isEmpty();
652	
653	        // Hard duplicate: a new owner whose identityKey (SHA-256 over telephone|email|soundex(lastName))
654	        // equals an existing, non-deleted owner's is the same identity and is always rejected. This is
655	        // now the single duplicate check: because the telephone is part of the key, two owners with the
656	        // same last name and postcode but different telephones no longer collide here and instead fall
657	        // through to the possible-duplicate (soft-match) flagging below.
658	        String identityKey = owner.getIdentityKey();
659	        for (Owner existing : this.clinicService.findAllOwners()) {
660	            if (existing.isDeleted()) {
661	                continue;
662	            }
663	            if (identityKey.equals(existing.getIdentityKey())) {
664	                throw new RestApiRejectionException(HttpStatus.CONFLICT,
665	                    "An owner with the same identity already exists");
666	            }
667	        }
668	        // Household member: another owner already shares this (last name, postcode) household. This
669	        // is no longer rejected as a duplicate — an exact byte-for-byte identity match is already
670	        // caught above, and a distinct additional household member is admitted with its membership
671	        // level capped (see below) at one above the current household maximum. The 'sharesHousehold'
672	        // flag now only signals that the caller vouches for the member, suppressing the
673	        // possible-duplicate flagging below.
674	        // A declared household member is not a suspected duplicate. Otherwise, flag an owner whose
675	        // last name shares an existing owner's soundex and postcode but whose identityKey differs.
676	        if (declaredHouseholdMember) {
677	            owner.setPossibleDuplicate(false);
678	            owner.setPossibleDuplicateOf(null);
679	        }
680	        else {
681	            Owner duplicateOf = possibleDuplicateOf(owner);
682	            owner.setPossibleDuplicate(duplicateOf != null);
683	            owner.setPossibleDuplicateOf(duplicateOf == null ? null : duplicateOf.getId());
684	        }
685	        owner.setNamesakeCount(namesakeCount(owner));
686	        owner.setHouseholdSize(householdMembers.size() + 1);
687	        // Level ceiling: a new owner's membershipLevel cannot exceed one above the current maximum
688	        // membershipLevel among their existing household members. With no existing member, no cap.
689	        if (householdMembers.isEmpty()) {
690	            owner.setMembershipLevelCap(null);
691	        }
692	        else {
693	            int maxHouseholdLevel = householdMembers.stream()
694	                .mapToInt(member -> ownerMapper.membershipLevel(member))
695	                .max()
696	                .getAsInt();
697	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
698	        }
699	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
700	        owner.setCapacityWarning(cityOwnerCount >= CITY_CAPACITY_WARNING_THRESHOLD);
701	        owner.setRegistrationDate(registrationDate);
702	        owner.setMemberId(memberIdFor(owner));
703	        this.clinicService.saveOwner(owner);
704	        if (idempotencyKey != null) {
705	            idempotentCreates.put(idempotencyKey, owner.getId());
706	        }
707	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
708	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
709	            ownerMapper.membershipLevel(owner));
710	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQ.incrementAndGet(), owner.getId(),
711	            primaryIdentifier(owner), ownerMapper.membershipLevel(owner), "OWNER_CREATED");
712	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
713	        // Enqueue a welcome notification carrying the owner id and the memberId.
714	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
715	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
716	        headers.setLocation(UriComponentsBuilder.newInstance()
717	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
718	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
719	    }
720	
721	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
722	    @Override
723	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
724	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
725	        if (currentOwner == null) {
726	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
727	        }
728	        currentOwner.setAddress(ownerFieldsDto.getAddress());
729	        currentOwner.setCity(ownerFieldsDto.getCity());
730	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
731	        currentOwner.setLastName(ownerFieldsDto.getLastName());
732	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
733	        currentOwner.setEmail(ownerFieldsDto.getEmail());
734	        if (!normalizeEmail(currentOwner)) {
735	            throw new RestApiRejectionException(HttpStatus.BAD_REQUEST,
736	                "The email address is not valid");
737	        }
738	        this.clinicService.saveOwner(currentOwner);
739	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
740	    }
741	
742	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
743	    @Transactional
744	    @Override
745	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
746	        Owner owner = this.clinicService.findOwnerById(ownerId);
747	        if (owner == null) {
748	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
749	        }
750	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
751	        owner.setDeleted(true);
752	        this.clinicService.saveOwner(owner);
753	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
754	    }
755	
756	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
757	    @Override
758	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
759	        Owner owner = this.clinicService.findOwnerById(ownerId);
760	        if (owner == null) {
761	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
762	        }
763	        HttpHeaders headers = new HttpHeaders();
764	        Pet pet = petMapper.toPet(petFieldsDto);
765	        owner.setId(ownerId);
766	        pet.setOwner(owner);
767	        pet.getType().setName(null);
768	        this.clinicService.savePet(pet);
769	        PetDto petDto = petMapper.toPetDto(pet);
770	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
771	            .buildAndExpand(pet.getId()).toUri());
772	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
773	    }
774	
775	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
776	    @Override
