332	        }
333	        else if (points <= 3) {
334	            level = 2;
335	        }
336	        else if (points <= 5) {
337	            level = 3;
338	        }
339	        else {
340	            level = 4;
341	        }
342	        Integer cap = owner.getMembershipLevelCap();
343	        if (cap != null && level > cap) {
344	            level = cap;
345	        }
346	        return level;
347	    }
