349	    /**
350	     * The owner's tenure in whole elapsed fiscal years: the number of fiscal-year boundaries
351	     * (1 July) crossed between {@code registrationDate} and the current date. A newly created
352	     * owner (registered in the current fiscal year) has zero tenure, and a missing
353	     * registrationDate (e.g. legacy records) is likewise treated as zero.
354	     */
355	    default long tenureFiscalYears(Owner owner) {
356	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
357	        if (registrationDate == null) {
358	            return 0;
359	        }
360	        long years = fiscalYearOf(java.time.LocalDate.now()) - fiscalYearOf(registrationDate);
361	        return Math.max(years, 0);
362	    }
363	
364	    /**
365	     * The fiscal year (a four-digit calendar year) that the given date falls in. The fiscal year
366	     * starts on 1 July and is identified by the calendar year in which it ends, so a date on or
367	     * after 1 July belongs to the fiscal year of the following calendar year.
368	     */
369	    default int fiscalYearOf(java.time.LocalDate date) {
370	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
371	    }
372	
373	    /**
374	     * The owner's fiscal year, formatted 'FY&lt;YY&gt;' where YY is the two-digit {@code <FY>}
375	     * segment of the memberId ({@code <REGION><FY><HASH8><CHK>}), i.e. the fiscal year of the
376	     * business-day-adjusted registrationDate captured at create time (the fiscal year starts on
377	     * 1 July). Returns {@code null} when the memberId is absent or carries no fiscal-year segment.
378	     */
379	    default String fiscalYear(Owner owner) {
380	        String memberId = owner.getMemberId();
381	        String region = memberRegion(memberId);
382	        if (region == null || memberId.length() < region.length() + 2) {
383	            return null;
384	        }
385	        String fy = memberId.substring(region.length(), region.length() + 2);
386	        if (!fy.matches("\\d{2}")) {
387	            return null;
388	        }
389	        return "FY" + fy;
390	    }
