392	    /**
393	     * The canonical link to this owner resource: {@code /api/owners/} followed by the
394	     * owner's id. Returns {@code null} when the owner has no id yet.
395	     */
396	    default String selfLink(Owner owner) {
397	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
398	    }
