401	
402	    @Mapping(target = "id", ignore = true)
403	    @Mapping(target = "pets", ignore = true)
404	    Owner toOwner(OwnerFieldsDto ownerDto);
405	
406	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
407	
408	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
409	
410	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
411	        OwnerPageDto ownerPageDto = new OwnerPageDto();
412	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
413	        ownerPageDto.setPage(ownerPage.getNumber());
414	        ownerPageDto.setSize(ownerPage.getSize());
415	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
416	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
417	        return ownerPageDto;
418	    }
