67	    @Column(name = "registration_date", columnDefinition = "DATE")
68	    private LocalDate registrationDate;
69	
70	    @Column(name = "birth_date", columnDefinition = "DATE")
71	    private LocalDate birthDate;
72	
73	    @Column(name = "member_id")
74	    private String memberId;
75	
76	    @Column(name = "household_id")
77	    private String householdId;
78	
79	    @Column(name = "namesake_count")
80	    private Integer namesakeCount;
81	
82	    @Column(name = "household_size")
83	    private Integer householdSize;
84	
85	    @Column(name = "membership_level_cap")
86	    private Integer membershipLevelCap;
87	
88	    @Column(name = "bulk_signup_warning")
89	    private Boolean bulkSignupWarning;
90	
91	    @Column(name = "possible_duplicate")
92	    private Boolean possibleDuplicate;
93	
94	    @Column(name = "possible_duplicate_of")
95	    private Integer possibleDuplicateOf;
96	
97	    @Column(name = "capacity_warning")
98	    private Boolean capacityWarning;
99	
100	    @Column(name = "deleted", nullable = false)
101	    private boolean deleted = false;
102	
103	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
104	    private Set<Pet> pets;
105	
106	    public String getTitle() {
107	        return this.title;
108	    }
