170	    public LocalDate getRegistrationDate() {
171	        return this.registrationDate;
172	    }
173	
174	    public void setRegistrationDate(LocalDate registrationDate) {
175	        this.registrationDate = registrationDate;
176	    }
177	
178	    public LocalDate getBirthDate() {
179	        return this.birthDate;
180	    }
181	
182	    public void setBirthDate(LocalDate birthDate) {
183	        this.birthDate = birthDate;
184	    }
185	
186	    public String getMemberId() {
187	        return this.memberId;
188	    }
189	
190	    public void setMemberId(String memberId) {
191	        this.memberId = memberId;
192	    }
193	
194	    public String getHouseholdId() {
195	        return this.householdId;
196	    }
197	
198	    public void setHouseholdId(String householdId) {
199	        this.householdId = householdId;
200	    }
201	
202	    public Integer getNamesakeCount() {
203	        return this.namesakeCount;
204	    }
205	
206	    public void setNamesakeCount(Integer namesakeCount) {
207	        this.namesakeCount = namesakeCount;
208	    }
209	
210	    public Integer getHouseholdSize() {
211	        return this.householdSize;
212	    }
213	
214	    public void setHouseholdSize(Integer householdSize) {
215	        this.householdSize = householdSize;
216	    }
217	
218	    /**
219	     * The ceiling applied to this owner's derived membership level: one above the highest
220	     * membership level among the household members that already existed when this owner was
221	     * created. {@code null} when the owner had no existing household members, in which case no
222	     * cap applies.
223	     */
224	    public Integer getMembershipLevelCap() {
225	        return this.membershipLevelCap;
226	    }
227	
228	    public void setMembershipLevelCap(Integer membershipLevelCap) {
229	        this.membershipLevelCap = membershipLevelCap;
230	    }
231	
232	    public Boolean getBulkSignupWarning() {
233	        return this.bulkSignupWarning;
234	    }
235	
236	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
237	        this.bulkSignupWarning = bulkSignupWarning;
238	    }
239	
240	    public Boolean getPossibleDuplicate() {
241	        return this.possibleDuplicate;
242	    }
243	
244	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
245	        this.possibleDuplicate = possibleDuplicate;
246	    }
247	
248	    public Integer getPossibleDuplicateOf() {
249	        return this.possibleDuplicateOf;
250	    }
251	
252	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
253	        this.possibleDuplicateOf = possibleDuplicateOf;
254	    }
255	
256	    public Boolean getCapacityWarning() {
257	        return this.capacityWarning;
258	    }
