260	    public void setCapacityWarning(Boolean capacityWarning) {
261	        this.capacityWarning = capacityWarning;
262	    }
263	
264	    public boolean isDeleted() {
265	        return this.deleted;
266	    }
267	
268	    public void setDeleted(boolean deleted) {
269	        this.deleted = deleted;
270	    }
271	
272	    /**
273	     * The derived identity key used for duplicate detection: the full lower-case hex SHA-256 of
274	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, treating a
275	     * {@code null} telephone or email as empty. The telephone is already stored in its normalized
276	     * (E.164) form and the email is lower-cased here for safety. Two owners are considered the same
277	     * only when their whole identity keys are equal.
278	     */
279	    @Transient
280	    public String getIdentityKey() {
281	        String tel = this.telephone == null ? "" : this.telephone;
282	        String mail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
283	        String input = tel + "|" + mail + "|" + soundex(this.lastName);
284	        try {
285	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
286	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
287	            StringBuilder sb = new StringBuilder(digest.length * 2);
288	            for (byte b : digest) {
289	                sb.append(String.format("%02x", b));
290	            }
291	            return sb.toString();
292	        }
293	        catch (java.security.NoSuchAlgorithmException e) {
294	            throw new IllegalStateException(e);
295	        }
296	    }
297	
298	    /**
299	     * American Soundex code for a name: the first letter followed by up to three digits derived from
300	     * the remaining consonants (b,f,p,v=1; c,g,j,k,q,s,x,z=2; d,t=3; l=4; m,n=5; r=6), with adjacent
301	     * duplicate codes (and codes separated only by 'h'/'w') collapsed, vowels acting as separators,
302	     * and the result right-padded with zeros to length 4. A {@code null} or letterless value yields an
303	     * empty string.
304	     */
305	    public static String soundex(String value) {
306	        if (value == null) {
307	            return "";
308	        }
309	        StringBuilder letters = new StringBuilder();
310	        for (int i = 0; i < value.length(); i++) {
311	            char c = Character.toUpperCase(value.charAt(i));
312	            if (c >= 'A' && c <= 'Z') {
313	                letters.append(c);
314	            }
315	        }
316	        if (letters.length() == 0) {
317	            return "";
318	        }
319	        StringBuilder code = new StringBuilder();
320	        code.append(letters.charAt(0));
321	        char prev = soundexCode(letters.charAt(0));
322	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
323	            char c = letters.charAt(i);
324	            if (c == 'H' || c == 'W') {
325	                continue;
326	            }
327	            char digit = soundexCode(c);
328	            if (digit != '0' && digit != prev) {
329	                code.append(digit);
330	            }
331	            if (c == 'A' || c == 'E' || c == 'I' || c == 'O' || c == 'U' || c == 'Y') {
332	                prev = '0';
333	            }
334	            else {
335	                prev = digit;
336	            }
337	        }
338	        while (code.length() < 4) {
339	            code.append('0');
340	        }
341	        return code.toString();
342	    }
343	
344	    /** Map a single upper-case letter to its Soundex digit ('0' for vowels/h/w/y). */
345	    private static char soundexCode(char c) {
346	        switch (c) {
347	            case 'B': case 'F': case 'P': case 'V':
348	                return '1';
349	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
350	                return '2';
351	            case 'D': case 'T':
352	                return '3';
353	            case 'L':
354	                return '4';
355	            case 'M': case 'N':
356	                return '5';
357	            case 'R':
358	                return '6';
359	            default:
360	                return '0';
361	        }
362	    }
363	
364	    protected Set<Pet> getPetsInternal() {
365	        if (this.pets == null) {
366	            this.pets = new HashSet<>();
367	        }
368	        return this.pets;
369	    }
370	
371	    protected void setPetsInternal(Set<Pet> pets) {
372	        this.pets = pets;
373	    }
374	
375	    public List<Pet> getPets() {
376	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
377	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
378	        return Collections.unmodifiableList(sortedPets);
379	    }
380	
381	    public void setPets(List<Pet> pets) {
382	        this.pets = new HashSet<>(pets);
383	    }
384	
385	    public void addPet(Pet pet) {
386	        getPetsInternal().add(pet);
387	        pet.setOwner(this);
388	    }
389	
390	    /**
391	     * Return the Pet with the given name, or null if none found for this Owner.
392	     *
393	     * @param name to test
394	     * @return true if pet name is already in use
395	     */
396	    public Pet getPet(String name) {
397	        return getPet(name, false);
398	    }
399	
400	    /**
401	     * Return the Pet with the given name, or null if none found for this Owner.
402	     *
403	     * @param name to test
404	     * @return true if pet name is already in use
405	     */
406	    public Pet getPet(String name, boolean ignoreNew) {
407	        name = name.toLowerCase();
408	        for (Pet pet : getPetsInternal()) {
409	            if (!ignoreNew || !pet.isNew()) {
410	                String compName = pet.getName();
411	                compName = compName.toLowerCase();
412	                if (compName.equals(name)) {
413	                    return pet;
414	                }
415	            }
416	        }
417	        return null;
418	    }
419	
420	    public Pet getPet(Integer petId) {
421	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
422	    }
423	
424	    @Override
425	    public String toString() {
426	        return new ToStringCreator(this)
427	
428	            .append("id", this.getId())
429	            .append("new", this.isNew())
430	            .append("lastName", this.getLastName())
431	            .append("firstName", this.getFirstName())
432	            .append("address", this.address)
433	            .append("city", this.city)
434	            .append("telephone", this.telephone)
435	            .append("email", this.email)
436	            .toString();
437	    }
438	}
